    private uint ReadMovemRegister(uint index) => index < 8 ? _data[index] : _address[index - 8];

    private void StoreMovemRegister(uint index, uint value)
    {
        if (index < 8)
            _data[index] = value;
        else
            _address[index - 8] = value;
    }
